{
  "summary": "Added an extractor enum quality `location` with values street, lobby, vault, readable directly from the prose as a choice. Existing checkpoints and the key gate are untouched; a later stage can gate transitions on this location.",
  "ops": [
    {
      "kind": "addQuality",
      "quality": {
        "key": "location",
        "type": "enum",
        "source": "extractor",
        "values": ["street", "lobby", "vault"],
        "read_as": "choice",
        "rubric": "Where are the crew right now? Answer street if the scene is outside or on the approach to the bank, lobby if they are inside the bank's public or staff area but not in the vault chamber, vault if they are inside or at the vault itself. Answer only one of: street, lobby, vault."
      }
    }
  ]
}

